import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"Slice: Storage & File Management","description":"","frontmatter":{},"headers":[],"relativePath":"en/15-storage-and-file-management.md","filePath":"en/15-storage-and-file-management.md"}'),n={name:"en/15-storage-and-file-management.md"};function l(o,e,r,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="slice-storage-file-management" tabindex="-1">Slice: Storage &amp; File Management <a class="header-anchor" href="#slice-storage-file-management" aria-label="Permalink to &quot;Slice: Storage &amp; File Management&quot;">​</a></h1><blockquote><p><strong>Binary asset and document storage with hybrid support: local filesystem in offline dev/tests and S3/MinIO compatibility for production.</strong></p></blockquote><hr><h2 id="_1-slice-overview" tabindex="-1">1. Slice Overview <a class="header-anchor" href="#_1-slice-overview" aria-label="Permalink to &quot;1. Slice Overview&quot;">​</a></h2><p>The <code>storage</code> slice (<code>apps/api/src/slices/storage/</code>) provides SoftForge&#39;s unified binary persistence engine:</p><ul><li><strong>Provider-Agnostic Storage Architecture:</strong> Abstracts physical storage through a standardized interface, allowing developers to run entirely offline on local disk (<code>uploads/</code>) while seamlessly switching to AWS S3, Cloudflare R2, or MinIO in production.</li><li><strong>100% Offline Development:</strong> During local development and <code>pytest</code> execution, files are persisted and retrieved directly from the filesystem without any network dependencies or external cloud credentials.</li><li><strong>Multi-Tenant Workspace Isolation:</strong> Files attached to a workspace are enforced by RBAC. Members from foreign workspaces receive HTTP 403 Forbidden when attempting to access private files.</li><li><strong>Public vs. Private Assets:</strong> Native support for public files (such as user avatars at <code>/storage/files/{id}/download</code>), enabling frictionless browser rendering without Authorization headers.</li><li><strong>Multipart Uploads &amp; Quota Limits:</strong> Endpoints are guarded with configurable file size limits (<code>MAX_UPLOAD_SIZE_MB</code>), rejecting oversized payloads with HTTP 413 Payload Too Large.</li><li><strong>Filename Sanitization &amp; Security:</strong> Filenames are sanitized via regex to prevent path traversal attacks (<code>../</code>) and shell injection. File uploads and deletions trigger structured audit logs and outbound webhooks (<code>file.uploaded</code>, <code>file.deleted</code>).</li></ul><hr><h2 id="_2-upload-download-sequence" tabindex="-1">2. Upload &amp; Download Sequence <a class="header-anchor" href="#_2-upload-download-sequence" aria-label="Permalink to &quot;2. Upload &amp; Download Sequence&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    autonumber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    actor Client as User / AI Agent</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant API as SoftForge API (FastAPI)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant RBAC as Tenant &amp; RBAC Guard</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Service as Storage Service</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Disk as Storage (Local / S3)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as PostgreSQL (stored_files)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client-&gt;&gt;API: POST /workspaces/{id}/storage/upload (multipart/form-data)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;RBAC: Validate membership (minimum Member role)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;Service: upload_workspace_file(...)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Disk: Write binary data (workspaces/{id}/{uuid}_{filename})</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;DB: Save record in stored_files</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;Client: HTTP 201 Created (StoredFileResponse with download_url)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over Client,Disk: Subsequent download</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client-&gt;&gt;API: GET /api/v1/storage/files/{id}/download</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;DB: Query file metadata</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;RBAC: Validate workspace authorization</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;Disk: Read binary bytes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;Client: HTTP 200 OK (Binary stream with Content-Type header)</span></span></code></pre></div><hr><h2 id="_3-slice-endpoints" tabindex="-1">3. Slice Endpoints <a class="header-anchor" href="#_3-slice-endpoints" aria-label="Permalink to &quot;3. Slice Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Route</th><th style="text-align:left;">Description</th><th style="text-align:left;">Minimum Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{workspace_id}/storage/upload</code></td><td style="text-align:left;">Uploads a file to the workspace</td><td style="text-align:left;"><code>Member</code></td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{workspace_id}/storage/files</code></td><td style="text-align:left;">Lists files attached to the workspace</td><td style="text-align:left;"><code>Viewer</code></td></tr><tr><td style="text-align:left;"><code>DELETE</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{workspace_id}/storage/files/{file_id}</code></td><td style="text-align:left;">Deletes physical file and database record</td><td style="text-align:left;"><code>Member</code></td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/api/v1/storage/files/{file_id}/download</code></td><td style="text-align:left;">Downloads or streams the file</td><td style="text-align:left;"><code>Public / Authenticated</code></td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/api/v1/users/me/avatar</code></td><td style="text-align:left;">Updates the authenticated user&#39;s profile avatar</td><td style="text-align:left;"><code>Authenticated</code></td></tr></tbody></table><hr><h2 id="_4-environment-configuration" tabindex="-1">4. Environment Configuration <a class="header-anchor" href="#_4-environment-configuration" aria-label="Permalink to &quot;4. Environment Configuration&quot;">​</a></h2><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Storage backend (local | s3 | minio)</span></span>
<span class="line"><span>STORAGE_BACKEND=local</span></span>
<span class="line"><span>STORAGE_LOCAL_DIR=uploads</span></span>
<span class="line"><span>MAX_UPLOAD_SIZE_MB=25</span></span>
<span class="line"><span></span></span>
<span class="line"><span># S3 / MinIO credentials (for staging and production)</span></span>
<span class="line"><span>S3_BUCKET_NAME=softforge-uploads</span></span>
<span class="line"><span>S3_REGION=us-east-1</span></span>
<span class="line"><span>S3_ENDPOINT_URL=http://minio:9000</span></span>
<span class="line"><span>S3_ACCESS_KEY_ID=minioadmin</span></span>
<span class="line"><span>S3_SECRET_ACCESS_KEY=minioadmin</span></span></code></pre></div><hr><h2 id="_5-automated-verification-testing" tabindex="-1">5. Automated Verification &amp; Testing <a class="header-anchor" href="#_5-automated-verification-testing" aria-label="Permalink to &quot;5. Automated Verification &amp; Testing&quot;">​</a></h2><p>The slice is verified with 100% deterministic Pytest coverage (<code>test_storage_slice.py</code>):</p><ol><li><strong>Upload &amp; Byte Parity:</strong> Multipart transmission, database verification, and byte-for-byte fidelity checks.</li><li><strong>Streaming &amp; Headers:</strong> Correct <code>Content-Type</code> and <code>Content-Disposition</code> header verification.</li><li><strong>Tenant Isolation:</strong> Immediate HTTP 403 Forbidden when accessing files across workspace boundaries.</li><li><strong>Public Avatars:</strong> Updating user profile avatar with public access enabled without authentication headers.</li></ol>`,19)])])}const u=a(n,[["render",l]]);export{h as __pageData,u as default};
